package com.example.fileservice.service;

import com.example.fileservice.config.FileUploadProperties;
import com.example.fileservice.exception.FileNotFoundException;
import com.example.fileservice.exception.InvalidContentTypeException;
import com.example.fileservice.exception.InvalidFileExtensionException;
import org.apache.commons.io.FilenameUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.InputStreamResource;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.InputStream;
import java.net.URLConnection;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Set;

@Service
public class FileService {

    private static final Logger logger = LoggerFactory.getLogger(FileService.class);
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(
            ".txt", ".pdf", ".jpg", ".jpeg", ".png", ".gif"
    );
    private static final Set<String> ALLOWED_MIME_TYPES = Set.of(
            "text/plain",
            "application/pdf",
            "image/jpeg",
            "image/png",
            "image/gif"
    );

    private final Path uploadDir;

    public FileService(FileUploadProperties properties) {
        this.uploadDir = properties.getUploadDir().toAbsolutePath().normalize();
        try {
            Files.createDirectories(this.uploadDir);
        } catch (IOException e) {
            throw new RuntimeException("Could not create upload directory: " + this.uploadDir, e);
        }
    }

    public Resource loadFileAsResource(String fileName) {
        // 1. Grundlegende Validierung
        if (fileName == null || fileName.isBlank()) {
            throw new IllegalArgumentException("fileName must not be null or blank");
        }

        // 2. Extrahiere den tatsächlichen Dateinamen (entfernt alle Pfadkomponenten)
        String safeFileName = FilenameUtils.getName(fileName);
        if (safeFileName.isEmpty()) {
            throw new SecurityException("Invalid file name: no name could be extracted");
        }
        // Zusätzlich: Verhindere "." und ".." sowie versteckte Dateien und Pfadseparatoren
        if (safeFileName.equals(".") || safeFileName.equals("..")) {
            throw new SecurityException("Invalid file name: dot entries are not allowed");
        }
        if (safeFileName.startsWith(".")) {
            throw new SecurityException("Hidden files are not allowed");
        }
        if (safeFileName.contains("/") || safeFileName.contains("\\")) {
            throw new SecurityException("Invalid file name: path separators not allowed");
        }

        // 3. Whitelist-Prüfung der Dateiendung (case-insensitive)
        String lowerFileName = safeFileName.toLowerCase();
        boolean extensionOk = ALLOWED_EXTENSIONS.stream().anyMatch(lowerFileName::endsWith);
        if (!extensionOk) {
            logger.warn("Attempt to access file with disallowed extension: {}", safeFileName);
            throw new InvalidFileExtensionException("File extension is not allowed: " + safeFileName);
        }

        // 4. Pfad normalisieren und sicherstellen, dass er im Upload-Verzeichnis liegt
        Path safePath = uploadDir.resolve(safeFileName).normalize();
        if (!safePath.startsWith(uploadDir)) {
            logger.warn("Path traversal attempt blocked: {} not under {}", safePath, uploadDir);
            throw new SecurityException("Access to file outside upload directory is denied");
        }

        // 5. Kanonischer Pfad (löst Symlinks auf) – nur wenn Datei existiert
        Path canonicalPath;
        try {
            canonicalPath = safePath.toRealPath();
        } catch (IOException e) {
            // Datei existiert noch nicht; verwende den normalisierten Pfad
            canonicalPath = safePath;
        }
        // Zusätzliche Prüfung: Auch der kanonische Pfad muss im uploadDir liegen
        if (!canonicalPath.startsWith(uploadDir)) {
            logger.warn("Canonical path traversal detected: {} not under {}", canonicalPath, uploadDir);
            throw new SecurityException("Access to file outside upload directory is denied");
        }

        // 6. Prüfe Existenz und Lesbarkeit
        if (!Files.exists(canonicalPath) || !Files.isRegularFile(canonicalPath)) {
            logger.warn("File not found: {}", canonicalPath);
            throw new FileNotFoundException("File not found: " + safeFileName);
        }
        if (!Files.isReadable(canonicalPath)) {
            logger.warn("File not readable: {}", canonicalPath);
            throw new SecurityException("File cannot be read: " + safeFileName);
        }

        // 7. MIME-Typ-Prüfung (CWE-434)
        String mimeType = null;
        try {
            mimeType = Files.probeContentType(canonicalPath);
        } catch (IOException e) {
            logger.debug("Could not probe content type via Files.probeContentType", e);
        }
        if (mimeType == null) {
            mimeType = URLConnection.guessContentTypeFromName(safeFileName);
        }
        if (mimeType == null || !ALLOWED_MIME_TYPES.contains(mimeType)) {
            logger.warn("Disallowed or undetermined MIME type: {} for file {}", mimeType, safeFileName);
            throw new InvalidContentTypeException("File content type is not allowed: " + (mimeType != null ? mimeType : "unknown"));
        }

        // 8. Datei öffnen und als Resource zurückgeben
        try {
            InputStream inputStream = Files.newInputStream(canonicalPath);
            Resource resource = new InputStreamResource(inputStream);
            logger.info("File served successfully: {} (canonical: {}, MIME: {})", safeFileName, canonicalPath, mimeType);
            return resource;
        } catch (IOException e) {
            logger.error("Error opening file stream: {}", canonicalPath, e);
            throw new RuntimeException("Could not open file: " + safeFileName, e);
        }
    }
}
