"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileController.java
package com.example.fileservice.controller;

import com.example.fileservice.exception.FileNotFoundException;
import com.example.fileservice.exception.InvalidContentTypeException;
import com.example.fileservice.exception.InvalidFileExtensionException;
import com.example.fileservice.service.FileService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.io.Resource;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.io.IOException;
import java.net.URLConnection;

@RestController
@RequestMapping("/api/files")
public class FileController {

    private static final Logger logger = LoggerFactory.getLogger(FileController.class);
    private final FileService fileService;

    public FileController(FileService fileService) {
        this.fileService = fileService;
    }

    @GetMapping
    public ResponseEntity<Resource> getFile(@RequestParam String fileName) {
        Resource resource = fileService.loadFileAsResource(fileName);

        // MIME-Typ erneut bestimmen (konsistent mit Service-Logik)
        String mimeType = URLConnection.guessContentTypeFromName(fileName);
        if (mimeType == null) {
            mimeType = "application/octet-stream";
        }

        return ResponseEntity.ok()
                .contentType(MediaType.parseMediaType(mimeType))
                .header(HttpHeaders.CONTENT_DISPOSITION, "inline; filename=\"" + fileName + "\"")
                .body(resource);
    }

    // Exception-Handler für die eigenen Exceptions
    @ExceptionHandler(FileNotFoundException.class)
    public ResponseEntity<String> handleFileNotFound(FileNotFoundException ex) {
        logger.warn("File not found: {}", ex.getMessage());
        return ResponseEntity.status(404).body(ex.getMessage());
    }

    @ExceptionHandler({InvalidFileExtensionException.class, InvalidContentTypeException.class})
    public ResponseEntity<String> handleInvalidFile(RuntimeException ex) {
        logger.warn("Invalid file request: {}", ex.getMessage());
        return ResponseEntity.status(400).body(ex.getMessage());
    }

    @ExceptionHandler(SecurityException.class)
    public ResponseEntity<String> handleSecurity(SecurityException ex) {
        logger.error("Security violation: {}", ex.getMessage());
        return ResponseEntity.status(403).body("Access denied");
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<String> handleBadRequest(IllegalArgumentException ex) {
        logger.warn("Bad request: {}", ex.getMessage());
        return ResponseEntity.status(400).body(ex.getMessage());
    }
}
