## Datei 2: `FileDownloadService.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FileDownloadService.java
package com.example.filedownload;

import org.springframework.core.io.InputStreamResource;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.io.InputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

@Service
public class FileDownloadService {

    // Basisverzeichnis – nur Dateien unterhalb dieses Pfades sind erlaubt.
    private static final Path BASE_PATH = Paths.get("data", "docs").toAbsolutePath().normalize();

    /**
     * Validiert den übergebenen Pfad, verhindert Path Traversal und lädt die Datei.
     *
     * @param userPath vom Benutzer übergebener, relativer Pfad (z. B. "report.pdf" oder "subdir/file.txt")
     * @return Resource der gelesenen Datei
     * @throws FileAccessException wenn der Pfad ungültig ist oder die Datei nicht existiert
     */
    public Resource loadFileAsResource(String userPath) {
        // 1. Kombinieren mit Basisverzeichnis und normalisieren
        Path requestedPath = BASE_PATH.resolve(userPath).normalize();

        // 2. Sicherheitsprüfung: Der normalisierte Pfad muss innerhalb des Basisverzeichnisses liegen
        if (!requestedPath.startsWith(BASE_PATH)) {
            // Keine genaue Fehlermeldung – generisch 404 werfen
            throw new FileAccessException("Datei nicht gefunden: " + userPath);
        }

        // 3. Existenzprüfung und echten, kanonischen Pfad ermitteln (löst symbolische Links auf)
        if (!Files.exists(requestedPath) || !Files.isReadable(requestedPath)) {
            throw new FileAccessException("Datei nicht gefunden: " + userPath);
        }

        try {
            // 4. Sicherstellen, dass die Datei eine reguläre Datei ist (kein Verzeichnis)
            if (!Files.isRegularFile(requestedPath)) {
                throw new FileAccessException("Datei nicht gefunden: " + userPath);
            }

            // 5. Optional: Auch nach Auflösen von Links prüfen, ob der Pfad noch im Basisverzeichnis liegt
            //    (toRealPath() wirft IOException bei nicht vorhandenen Dateien, daher erst nach Existenzprüfung)
            Path realPath = requestedPath.toRealPath();
            if (!realPath.startsWith(BASE_PATH)) {
                throw new FileAccessException("Datei nicht gefunden: " + userPath);
            }

            // 6. Datei als InputStreamResource laden
            InputStream inputStream = Files.newInputStream(realPath);
            return new InputStreamResource(inputStream);

        } catch (IOException e) {
            throw new FileAccessException("Fehler beim Lesen der Datei: " + userPath, e);
        }
    }
}
