package com.example.filedownload;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;

import java.util.Map;

@ControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(FileAccessException.class)
    public ResponseEntity<Map<String, String>> handleFileAccessException(FileAccessException ex) {
        // Einheitliche Fehlerantwort – kein Unterschied zwischen "nicht existent" und "verboten"
        return ResponseEntity.status(HttpStatus.NOT_FOUND)
                .body(Map.of("error", "Datei nicht gefunden"));
    }

    // Optional: Andere Exceptions
    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, String>> handleGenericException(Exception ex) {
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Map.of("error", "Interner Serverfehler"));
    }
}
