## 2. Service

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// PingService.java
package com.example.ping.service;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

@Service
public class PingService {

    private static final Logger logger = LoggerFactory.getLogger(PingService.class);
    private static final int TIMEOUT_SECONDS = 30;
    private static final Pattern TARGET_PATTERN = Pattern.compile("^[a-zA-Z0-9.:-]+$");

    public String executePing(String target, int count) {
        // Validate input
        if (target == null || !TARGET_PATTERN.matcher(target).matches()) {
            logger.error("Invalid target (contains disallowed characters): {}", target);
            throw new IllegalArgumentException("Target must be a valid hostname or IP address");
        }
        if (count < 1 || count > 100) {
            logger.error("Invalid count: {}", count);
            throw new IllegalArgumentException("Count must be between 1 and 100");
        }

        try {
            // Build platform-specific ping command (no shell involvement)
            ProcessBuilder pb = new ProcessBuilder(buildPingCommand(target, count));
            pb.redirectErrorStream(true);
            Process process = pb.start();

            // Wait for completion with timeout
            boolean finished = process.waitFor(TIMEOUT_SECONDS, TimeUnit.SECONDS);
            if (!finished) {
                process.destroyForcibly();
                logger.warn("Ping timeout for target: {}", target);
                return "Ping timed out after " + TIMEOUT_SECONDS + " seconds.";
            }

            // Read output
            StringBuilder output = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append(System.lineSeparator());
                }
            }

            int exitCode = process.exitValue();
            logger.info("Ping executed. Target: {}, Exit code: {}", target, exitCode);
            return output.toString();

        } catch (IOException | InterruptedException e) {
            logger.error("Error executing ping: {}", e.getMessage());
            Thread.currentThread().interrupt();
            return "Failed to execute ping: " + e.getMessage();
        }
    }

    private String[] buildPingCommand(String target, int count) {
        String os = System.getProperty("os.name").toLowerCase();
        if (os.contains("win")) {
            // Windows: direct call to ping.exe (no cmd.exe)
            return new String[]{"ping", "-n", String.valueOf(count), target};
        } else {
            // Unix/Linux: ping -c <count> <target>
            return new String[]{"ping", "-c", String.valueOf(count), target};
        }
    }
}
