package com.example.ping.validation;

import org.springframework.stereotype.Component;

import java.util.regex.Pattern;

@Component
public class PingValidation {

    // Whitelist: Buchstaben, Ziffern, Punkt, Bindestrich, Doppelpunkt (für IPv6)
    private static final Pattern TARGET_PATTERN = Pattern.compile(
            "^[a-zA-Z0-9.\\-:]+$"
    );

    // Maximale Anzahl Ping-Pakete, um Flooding zu verhindern
    private static final int MAX_COUNT = 10;

    public boolean isValidTarget(String target) {
        return target != null && !target.isEmpty() && TARGET_PATTERN.matcher(target).matches();
    }

    public boolean isValidCount(int count) {
        return count >= 1 && count <= MAX_COUNT;
    }
}
