## 4. Rate Limiter (In-Memory Token Bucket)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimiter.java
package com.example.ping.security;

import org.springframework.stereotype.Component;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;

/**
 * Einfacher IP-basierter Token-Bucket-Rate-Limiter.
 * Erlaubt maximal {@code MAX_REQUESTS} Anfragen pro {@code TIME_WINDOW_SECONDS} Sekunden.
 */
@Component
public class RateLimiter {

    private static final int MAX_REQUESTS = 10;          // Max. 10 Requests
    private static final int TIME_WINDOW_SECONDS = 60;   // pro Minute

    // Speicher: IP -> {Anzahl Requests, Reset-Zeitstempel}
    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();

    public boolean tryConsume(String ip) {
        long now = System.nanoTime();
        long windowNanos = TimeUnit.SECONDS.toNanos(TIME_WINDOW_SECONDS);

        Bucket bucket = buckets.compute(ip, (key, existing) -> {
            if (existing == null || now - existing.resetTime >= windowNanos) {
                // Neues Fenster
                return new Bucket(1, now);
            } else if (existing.count < MAX_REQUESTS) {
                // Erhöhe Zähler
                existing.count++;
                return existing;
            } else {
                // Limit erreicht
                return existing;
            }
        });

        return bucket.count <= MAX_REQUESTS;
    }

    private static class Bucket {
        int count;
        long resetTime; // Nanozeit

        Bucket(int count, long resetTime) {
            this.count = count;
            this.resetTime = resetTime;
        }
    }
}
