### 4. GuestbookController.java

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GuestbookController.java
package com.example.guestbook;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.util.HtmlUtils;

import javax.validation.Valid;
import java.util.List;

/**
 * REST-Controller für das Gästebuch.
 * Stellt POST (Eintrag hinzufügen) und GET (HTML-Seite mit allen Einträgen) bereit.
 * Alle Ausgaben werden HTML-eskapiert (XSS-Prävention).
 * Eingaben werden validiert (Allowlist) – siehe GuestbookEntryRequest.
 */
@RestController
@RequestMapping("/api/guestbook")
public class GuestbookController {

    private static final Logger log = LoggerFactory.getLogger(GuestbookController.class);

    @Autowired
    private GuestbookRepository repository;

    /**
     * POST /api/guestbook/entry
     * Fügt einen neuen Gästebucheintrag hinzu.
     * Führt Input-Validierung und -Sanitization durch.
     *
     * @param request validiertes DTO mit name und text
     * @return 201 CREATED mit dem gespeicherten Eintrag (IDs)
     */
    @PostMapping("/entry")
    public ResponseEntity<GuestbookEntry> addEntry(@Valid @RequestBody GuestbookEntryRequest request) {
        log.info("Neuer Eintrag von: {}", request.getName());

        // Zusätzliche Sicherheit: HTML-Encoding sicherheitshalber (obwohl Eingabe bereits gefiltert wurde)
        String safeName = HtmlUtils.htmlEscape(request.getName());
        String safeText = HtmlUtils.htmlEscape(request.getText());

        GuestbookEntry entry = new GuestbookEntry(safeName, safeText);
        GuestbookEntry saved = repository.save(entry);

        log.info("Eintrag gespeichert mit ID: {}", saved.getId());
        return ResponseEntity.status(HttpStatus.CREATED).body(saved);
    }

    /**
     * GET /api/guestbook/entries
     * Gibt eine einfache HTML-Seite mit allen Einträgen zurück.
     * Alle Daten werden vor der Einfügung in die Seite HTML-eskapiert.
     * Content-Type ist text/html.
     *
     * @return HTML-String
     */
    @GetMapping(value = "/entries", produces = MediaType.TEXT_HTML_VALUE)
    public String getEntriesAsHtml() {
        List<GuestbookEntry> entries = repository.findAll();

        StringBuilder html = new StringBuilder();
        html.append("<!DOCTYPE html><html><head><title>Gästebuch</title></head><body>");
        html.append("<h1>Gästebuch</h1>");
        html.append("<ul>");

        if (entries.isEmpty()) {
            html.append("<li>Keine Einträge vorhanden.</li>");
        } else {
            for (GuestbookEntry entry : entries) {
                String safeName = HtmlUtils.htmlEscape(entry.getName());
                String safeText = HtmlUtils.htmlEscape(entry.getText());
                html.append("<li><strong>").append(safeName).append("</strong>: ").append(safeText).append("</li>");
            }
        }

        html.append("</ul></body></html>");
        return html.toString();
    }
}
