### 5. SecurityConfig.java

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.guestbook;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.authentication.builders.AuthenticationManagerBuilder;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;

/**
 * Spring Security Konfiguration.
 * Authentifizierung per Basic Auth mit einem In-Memory-Benutzer.
 * Authorisierung: Nur Benutzer mit Rolle USER dürfen auf das Gästebuch zugreifen.
 * CSRF ist deaktiviert (REST-API ohne Session).
 * Der Rate-Limiting-Filter wird über die HTTP-Konfiguration registriert.
 */
@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    @Override
    protected void configure(AuthenticationManagerBuilder auth) throws Exception {
        auth.inMemoryAuthentication()
                .withUser("user")
                .password(passwordEncoder().encode("password"))
                .roles("USER");
    }

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .csrf().disable() // Nur für REST-API ohne Session
            .authorizeRequests()
                .antMatchers("/api/guestbook/**").hasRole("USER")
                .anyRequest().denyAll()
            .and()
            .httpBasic(); // Basisauthentifizierung
        // Der RateLimitFilter wird als eigenes Bean hinzugefügt (siehe Filter-Klasse)
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
