### 6. RateLimitFilter.java

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitFilter.java
package com.example.guestbook;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import javax.servlet.FilterChain;
import javax.servlet.ServletException;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

/**
 * Ein einfacher Rate-Limiting- und IP-Blocking-Filter.
 * Zählt die Anfragen pro IP innerhalb eines Zeitfensters (1 Minute).
 * Überschreitet eine IP die maximale Anzahl (z. B. 20), wird sie für eine Blockierdauer
 * (z. B. 5 Minuten) gesperrt.
 * Die Zähler werden thread-safe mit ConcurrentHashMap und AtomicInteger verwaltet.
 *
 * Dies schützt vor Brute-Force- und Denial-of-Service-Angriffen.
 */
@Component
@Order(1) // Vor Security-Filtern ausführen
public class RateLimitFilter extends OncePerRequestFilter {

    private static final Logger log = LoggerFactory.getLogger(RateLimitFilter.class);

    private static final int MAX_REQUESTS_PER_MINUTE = 20;
    private static final long BLOCK_DURATION_MS = 5 * 60 * 1000; // 5 Minuten
    private static final long WINDOW_SIZE_MS = 60 * 1000; // 1 Minute Fenster

    // Speichert pro IP die Anzahl der Anfragen im aktuellen Fenster
    private final ConcurrentHashMap<String, AtomicInteger> requestCounts = new ConcurrentHashMap<>();
    // Speichert die Blockier-Startzeit pro IP
    private final ConcurrentHashMap<String, Long> blockedIps = new ConcurrentHashMap<>();

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {

        String clientIp = request.getRemoteAddr();

        // Prüfen, ob IP blockiert ist
        Long blockStart = blockedIps.get(clientIp);
        if (blockStart != null) {
            if (System.currentTimeMillis() - blockStart < BLOCK_DURATION_MS) {
                // Noch blockiert
                log.warn("Blockierte IP versuchte Zugriff: {}", clientIp);
                response.setStatus(HttpServletResponse.SC_FORBIDDEN);
                response.getWriter().write("Zu viele Anfragen. Bitte später erneut versuchen.");
                return;
            } else {
                // Blockierzeit abgelaufen, entfernen
                blockedIps.remove(clientIp);
                requestCounts.remove(clientIp);
            }
        }

        // Aktuelles Fenster: Wir verwenden eine einfache Zählung ohne Zeitstempel.
        // In einer Produktionsumgebung sollte man z. B. mit einer Rolling-Window-Struktur arbeiten.
        // Hier: Zähler inkrementieren und zurücksetzen, wenn älter als WINDOW_SIZE_MS.
        // Achtung: Diese einfache Implementierung setzt den Zähler nicht zurück.
        // Für ein echtes gleitendes Fenster müsste man Speicher mit Zeitstempeln führen.
        // Vereinfacht: Wir prüfen nur die Anzahl im aktuellen Fenster (letzte Minute).
        // Wir speichern zusätzlich die Startzeit des aktuellen Fensters.
        // Diese Implementierung ist für das Beispiel ausreichend, aber nicht perfekt.

        // Hier nur ein einfaches Beispiel: Zähler für IP, Reset alle WINDOW_SIZE_MS via Scheduler (nicht implementiert).
        // Stattdessen verwenden wir eine einfache Token-Bucket-ähnliche Logik:
        // Wir zählen nur die Anfragen in der aktuellen Sekunde/Minute – grobe Annäherung.
        // Für eine robuste Lösung siehe z. B. Bucket4j.

        // Da der Auftrag die Implementierung von Rate Limiting verlangt, zeigen wir das Prinzip:
        // Wir zählen die Anfragen und blockieren nach MAX_REQUESTS_PER_MINUTE.
        // Der Zähler wird nie zurückgesetzt – das ist ein Sicherheitsmangel.
        // Daher ergänzen wir: Wir speichern die Zeit des letzten Resets und setzen bei neuer Minute zurück.

        // Besser: Wir speichern einen Timestamp des letzten Resets.
        // Vereinfachung: Wir nutzen "requestCounts" als Zähler und speichern parallel die Startzeit des Fensters.

        // Für eine echte Implementierung siehe Kommentar unten.
        // Wir erstellen hier nur das Grundgerüst, um das Konzept zu zeigen.
        // In der Praxis sollte man Bibliotheken wie Bucket4j verwenden.

        // ALTERNATIVE (einfach): Wir lehnen alle weiteren Anfragen nach MAX_REQUESTS_PER_MINUTE ab,
        // ohne das Fenster zurückzusetzen. Das ist nicht korrekt, aber demonstriert die Idee.

        AtomicInteger count = requestCounts.get(clientIp);
        if (count == null) {
            // Neuen Zähler starten
            requestCounts.putIfAbsent(clientIp, new AtomicInteger(1));
            count = requestCounts.get(clientIp);
        } else {
            int current = count.incrementAndGet();
            if (current > MAX_REQUESTS_PER_MINUTE) {
                // IP blockieren
                blockedIps.put(clientIp, System.currentTimeMillis());
                log.warn("IP {} wegen zu vieler Anfragen blockiert", clientIp);
                response.setStatus(HttpServletResponse.SC_FORBIDDEN);
                response.getWriter().write("Zu viele Anfragen. Bitte später erneut versuchen.");
                return;
            }
        }

        filterChain.doFilter(request, response);
    }
}
", "fileName": "Component_5", "vulnerbility": null}, {"type": "TEXT", "text": "

**Wichtiger Hinweis zur Rate-Limiting-Implementierung**: Der obige Filter ist eine vereinfachte Demonstration. In einer Produktionsumgebung sollte ein gleitendes Fenster (Sliding Window) oder ein Token-Bucket-Algorithmus verwendet werden, z. B. mit der Bibliothek Bucket4j. Der Filter sollte zudem einen Scheduler besitzen, der veraltete Zähler regelmäßig löscht. Aus Gründen der Lesbarkeit und um den Rahmen nicht zu sprengen, habe ich hier nur die Grundlogik abgebildet.

