package com.example.customer;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import org.springframework.stereotype.Repository;

import java.util.List;

@Repository
public interface CustomerRepository extends JpaRepository<Customer, Long> {

    /**
     * Sucht Kunden, deren Name, E-Mail oder Stadt den Suchbegriff (case‑insensitive) enthalten.
     * Der Suchbegriff wird als Parameter gebunden → sicher gegen SQL Injection.
     */
    @Query("SELECT c FROM Customer c WHERE " +
           "LOWER(c.name) LIKE LOWER(CONCAT('%', :searchTerm, '%')) OR " +
           "LOWER(c.email) LIKE LOWER(CONCAT('%', :searchTerm, '%')) OR " +
           "LOWER(c.city) LIKE LOWER(CONCAT('%', :searchTerm, '%'))")
    List<Customer> searchByTerm(@Param("searchTerm") String searchTerm);
}
