### 4. REST-Controller mit Eingabevalidierung

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerController.java
package com.example.customer;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import javax.validation.constraints.Size;
import java.util.List;

@RestController
@RequestMapping("/api/customers")
public class CustomerController {

    @Autowired
    private CustomerService customerService;

    @GetMapping("/search")
    public ResponseEntity<List<Customer>> searchCustomers(
            @RequestParam("search")
            @Size(min = 1, max = 100, message = "Search term must be between 1 and 100 characters")
            String searchTerm) {

        // Zweite Validierungsebene: Nur erlaubte Zeichen akzeptieren
        // (alphanumerisch, Leerzeichen, Umlaute, Bindestrich, Punkt, Unterstrich, @)
        if (!searchTerm.matches("[a-zA-Z0-9 äöüÄÖÜß\\-@._]+")) {
            return ResponseEntity.badRequest().build();
        }

        List<Customer> customers = customerService.searchCustomers(searchTerm);
        return ResponseEntity.ok(customers);
    }
}
