### 4. Service-Implementierung

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// LdapUserServiceImpl.java
package com.example.demo.service;

import com.example.demo.dto.UserDto;
import com.example.demo.exception.InvalidInputException;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import javax.naming.NamingEnumeration;
import javax.naming.NamingException;
import javax.naming.directory.*;
import javax.naming.ldap.InitialLdapContext;
import javax.naming.ldap.LdapContext;
import java.util.ArrayList;
import java.util.Hashtable;
import java.util.List;

@Service
public class LdapUserServiceImpl implements LdapUserService {

    @Value("${ldap.url}")
    private String ldapUrl;

    @Value("${ldap.base}")
    private String baseDn;

    @Value("${ldap.user}")
    private String ldapUser;

    @Value("${ldap.password}")
    private String ldapPassword;

    @Override
    public List<UserDto> searchUsersByUsername(String username) {
        // Allowlist-Validierung (nur Buchstaben, Ziffern, Punkt, Unterstrich, Bindestrich)
        if (username == null || !username.matches("[a-zA-Z0-9._-]+")) {
            throw new InvalidInputException("Username contains invalid characters");
        }

        Hashtable<String, String> env = new Hashtable<>();
        env.put(Context.INITIAL_CONTEXT_FACTORY, "com.sun.jndi.ldap.LdapCtxFactory");
        env.put(Context.PROVIDER_URL, ldapUrl);
        env.put(Context.SECURITY_AUTHENTICATION, "simple");
        env.put(Context.SECURITY_PRINCIPAL, ldapUser);
        env.put(Context.SECURITY_CREDENTIALS, ldapPassword);

        List<UserDto> users = new ArrayList<>();

        try {
            LdapContext ctx = new InitialLdapContext(env, null);

            // Sicherer parameterisierter Filter – {0} wird durch den Benutzereingabewert ersetzt,
            // aber JNDI escaped die Werte automatisch, sodass keine LDAP-Injection möglich ist.
            String filter = "(&(uid={0})(objectClass=person))";
            SearchControls controls = new SearchControls();
            controls.setSearchScope(SearchControls.SUBTREE_SCOPE);
            controls.setReturningAttributes(new String[]{"uid", "displayName", "mail", "department"});

            // Der dritte Parameter ist das Object-Array mit den Werten für die Platzhalter
            NamingEnumeration<SearchResult> results = ctx.search(baseDn, filter, new Object[]{username}, controls);

            while (results.hasMore()) {
                SearchResult result = results.next();
                Attributes attrs = result.getAttributes();

                String uid = getAttributeValue(attrs, "uid");
                String displayName = getAttributeValue(attrs, "displayName");
                String mail = getAttributeValue(attrs, "mail");
                String department = getAttributeValue(attrs, "department");

                users.add(new UserDto(uid, displayName, mail, department));
            }

            ctx.close();
        } catch (NamingException e) {
            // Loggen und in eine allgemeine Laufzeitausnahme umwandeln
            throw new RuntimeException("LDAP search failed", e);
        }

        return users;
    }

    private String getAttributeValue(Attributes attrs, String attrName) throws NamingException {
        Attribute attr = attrs.get(attrName);
        if (attr != null) {
            Object value = attr.get();
            return value != null ? value.toString() : null;
        }
        return null;
    }
}
", "fileName": "Component_3", "vulnerbility": null}, {"type": "TEXT", "text": "

### 5. Controller

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UserDirectoryController.java
package com.example.demo.controller;

import com.example.demo.dto.UserDto;
import com.example.demo.exception.InvalidInputException;
import com.example.demo.service.LdapUserService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequestMapping("/directory")
public class UserDirectoryController {

    private final LdapUserService ldapUserService;

    public UserDirectoryController(LdapUserService ldapUserService) {
        this.ldapUserService = ldapUserService;
    }

    @GetMapping("/users")
    public ResponseEntity<List<UserDto>> getUsers(@RequestParam("username") String username) {
        try {
            List<UserDto> users = ldapUserService.searchUsersByUsername(username);
            return ResponseEntity.ok(users);
        } catch (InvalidInputException e) {
            return ResponseEntity.badRequest().build();
        } catch (RuntimeException e) {
            // Allgemeiner LDAP-Fehler – als 500 zurückgeben
            return ResponseEntity.internalServerError().build();
        }
    }
}
