### 2. ExportController.java  
Der Controller implementiert alle geforderten Sicherheitsmaßnahmen:

| Sicherheitsziel | Umsetzung | Betroffene CWE |
|----------------|-----------|----------------|
| **Path Traversal verhindern** (CWE-22, CWE-36) | 1. Whitelist: `^[a-zA-Z0-9._-]+$`<br>2. Pfad normalisieren (`Path.normalize()`)<br>3. Prüfung, ob der normalisierte Pfad **mit dem exports-Verzeichnis beginnt** | CWE-22, CWE-36 |
| **Information Disclosure vermeiden** (CWE-200, CWE-209) | Fehlermeldungen enthalten nur generische Texte (`"File not found"`, `"Invalid filename format"`) | CWE-200, CWE-209 |
| **Sicherer Datei-Upload per Header** | Content-Disposition mit `attachment` und RFC 5987‑konformer UTF-8‑Kodierung | CWE-200 (kein Leaken des internen Pfads) |
| **Zugriff nur auf reguläre Dateien** | `Files.isRegularFile()` schließt Verzeichnisse und symbolische Links aus | CWE-59, CWE-61 |
| **Deny by Default** | Standardmäßig wird der Zugriff verweigert, nur explizit erlaubte Muster passieren | A01:2025 Broken Access Control |

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ExportController.java
package com.example.export;

import org.apache.commons.io.FilenameUtils;
import org.springframework.core.io.InputStreamResource;
import org.springframework.core.io.Resource;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

@RestController
@RequestMapping("/export")
public class ExportController {

    private final Path exportsDirectory;

    public ExportController() {
        this.exportsDirectory = Paths.get(System.getProperty("user.dir"), "exports")
                                     .toAbsolutePath()
                                     .normalize();
        try {
            Files.createDirectories(exportsDirectory);
        } catch (IOException e) {
            throw new RuntimeException("Failed to initialize exports directory", e);
        }
    }

    @GetMapping
    public ResponseEntity<?> downloadFile(@RequestParam("filename") String filename) {
        // Sicherheitsmaßnahme: Nur den Dateinamen extrahieren (entfernt alle Verzeichnisteile)
        String safeFilename = FilenameUtils.getName(filename);

        // Whitelist-Validierung des bereinigten Dateinamens
        if (safeFilename == null || !safeFilename.matches("^[a-zA-Z0-9._-]+$")) {
            return ResponseEntity.badRequest()
                                 .body(new ErrorResponse("Invalid filename format"));
        }

        // Pfad auflösen und normalisieren
        Path requestedPath = exportsDirectory.resolve(safeFilename).normalize();

        // Prüfung, ob der Pfad noch im exports-Verzeichnis liegt
        if (!requestedPath.startsWith(exportsDirectory)) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN)
                                 .body(new ErrorResponse("Access denied"));
        }

        // Existenz- und Typ-Prüfung (kein Verzeichnis, kein Symlink usw.)
        if (!Files.exists(requestedPath) || !Files.isRegularFile(requestedPath)) {
            return ResponseEntity.status(HttpStatus.NOT_FOUND)
                                 .body(new ErrorResponse("File not found"));
        }

        // Leserechte prüfen
        if (!Files.isReadable(requestedPath)) {
            return ResponseEntity.status(HttpStatus.FORBIDDEN)
                                 .body(new ErrorResponse("Access denied"));
        }

        // Datei als Stream zurückgeben
        try {
            InputStream inputStream = new FileInputStream(requestedPath.toFile());
            InputStreamResource resource = new InputStreamResource(inputStream);

            // Sicheren Content-Disposition-Header setzen (RFC 5987)
            ContentDisposition contentDisposition = ContentDisposition.builder("attachment")
                    .filename(safeFilename, StandardCharsets.UTF_8)
                    .build();

            HttpHeaders headers = new HttpHeaders();
            headers.setContentDisposition(contentDisposition);

            // Mime-Typ bestimmen (Fallback application/octet-stream)
            MediaType mediaType = MediaType.APPLICATION_OCTET_STREAM;
            try {
                String mimeType = Files.probeContentType(requestedPath);
                if (mimeType != null) {
                    mediaType = MediaType.parseMediaType(mimeType);
                }
            } catch (IOException ignored) {
                // Fallback bleibt erhalten
            }

            return ResponseEntity.ok()
                    .headers(headers)
                    .contentLength(Files.size(requestedPath))
                    .contentType(mediaType)
                    .body(resource);
        } catch (IOException e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                                 .body(new ErrorResponse("Could not read file"));
        }
    }
}
