#### 2. Validator für Redirect-URLs (Kernlogik)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectValidator.java
package com.example.security.redirect.service;

import com.example.security.redirect.config.AllowedRedirectUrls;
import org.springframework.stereotype.Service;
import org.springframework.web.util.UriComponents;
import org.springframework.web.util.UriComponentsBuilder;

import java.net.URI;
import java.util.List;

@Service
public class RedirectValidator {

    private final List<String> allowedHosts;

    public RedirectValidator(AllowedRedirectUrls allowedUrls) {
        this.allowedHosts = allowedUrls.getAllowedHosts();
    }

    /**
     * Validiert die übergebene URL und gibt bei Erfolg die URI zurück.
     * @param rawUrl die unvalidierte URL aus dem Query-Parameter
     * @return die validierte URI
     * @throws InvalidUrlException wenn die URL nicht zur Whitelist passt
     */
    public URI validateRedirectUrl(String rawUrl) {
        if (rawUrl == null || rawUrl.isBlank()) {
            throw new InvalidUrlException("Redirect URL is missing or empty");
        }

        // Versuche, die URL zu parsen
        UriComponents uriComponents;
        try {
            uriComponents = UriComponentsBuilder.fromUriString(rawUrl).build();
        } catch (Exception e) {
            throw new InvalidUrlException("Malformed URL: " + rawUrl, e);
        }

        // Host ermitteln
        String host = uriComponents.getHost();

        // Fall 1: Kein Host → relative URL (kein Redirect-Risiko, da gleiche Domain)
        if (host == null) {
            // Prüfe, ob es eine protokollrelative URL (//evil.com) ist
            if (rawUrl.startsWith("//")) {
                // Protokollrelative URLs haben keinen Host im UriComponents, aber sie sind extern.
                // Extrahiere den Host manuell nach "//"
                String withoutProtocol = rawUrl.substring(2);
                int slashIndex = withoutProtocol.indexOf('/');
                String extractedHost = (slashIndex == -1) ? withoutProtocol : withoutProtocol.substring(0, slashIndex);
                if (!allowedHosts.contains(extractedHost)) {
                    throw new InvalidUrlException("Protocol-relative URL host not allowed: " + extractedHost);
                }
            }
            // relative URL ohne Host ist immer sicher (innerhalb der App)
            return URI.create(rawUrl);
        }

        // Fall 2: Absoluten Host prüfen (inklusive Port? Wir ignorieren Port für die Whitelist)
        if (!allowedHosts.contains(host)) {
            throw new InvalidUrlException("Redirect host not allowed: " + host);
        }

        // Zusätzlich: Pfad auf erlaubte Zeichen prüfen (CWE-89 Sanitization – hier nur illustrative Prüfung)
        String path = uriComponents.getPath();
        if (path != null && !path.matches("^[/a-zA-Z0-9._~%!$&'()*+,;=:@-]*$")) {
            throw new InvalidUrlException("Path contains forbidden characters: " + path);
        }

        return URI.create(rawUrl);
    }
}
