package com.example.security.redirect.controller;

import com.example.security.redirect.dto.RedirectResponse;
import com.example.security.redirect.service.InvalidUrlException;
import com.example.security.redirect.service.RedirectValidator;
import org.springframework.http.HttpHeaders;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.net.URI;

@RestController
public class RedirectController {

    private final RedirectValidator redirectValidator;

    public RedirectController(RedirectValidator redirectValidator) {
        this.redirectValidator = redirectValidator;
    }

    @GetMapping("/redirect")
    public ResponseEntity<RedirectResponse> handleRedirect(
            @RequestParam("redirectUrl") String redirectUrl) {

        URI validatedUri = redirectValidator.validateRedirectUrl(redirectUrl);

        RedirectResponse body = new RedirectResponse(
                "Redirect URL validated successfully.",
                validatedUri.toString()
        );

        return ResponseEntity.ok()
                .header(HttpHeaders.LOCATION, validatedUri.toString())
                .body(body);
    }
}
