#### 9. Filter-Konfiguration in Spring Boot

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// FilterConfig.java
package com.example.security.redirect.config;

import com.example.security.redirect.filter.RateLimitingFilter;
import org.springframework.boot.web.servlet.FilterRegistrationBean;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class FilterConfig {

    @Bean
    public FilterRegistrationBean<RateLimitingFilter> rateLimitingFilter() {
        FilterRegistrationBean<RateLimitingFilter> registration = new FilterRegistrationBean<>();
        registration.setFilter(new RateLimitingFilter());
        registration.addUrlPatterns("/redirect/*");
        registration.setOrder(1);
        return registration;
    }
}
