---

### Erläuterung der Sicherheitsmaßnahmen

1. **Whitelist für Hosts (CWE-20 / Open Redirect Prevention)**  
   Der `RedirectValidator` prüft, ob die eingegebene URL einen Host enthält, der in der konfigurierten Liste (`allowed-hosts`) steht. Relative URLs (ohne Host) werden akzeptiert, da sie nicht auf eine externe Domain verweisen. Protokollrelative URLs (`//evil.com`) werden erkannt und ebenfalls gegen die Whitelist geprüft. Damit ist es einem Angreifer nicht möglich, die Anwendung als offenen Redirector zu missbrauchen.

2. **Pfad-Sanitization (CWE-89 – exemplarisch)**  
   Obwohl SQL Injection hier nicht direkt relevant ist, wird zusätzlich der Pfad gegen ein restriktives Zeichenmuster geprüft. Dies verhindert, dass bösartige Zeichen wie `<script>` oder Steuerzeichen in die URL eingeschleust werden – eine defensive Maßnahme gegen Cross-Site-Scripting (XSS), falls die URL später auf einer Seite ausgegeben wird.

3. **Rate Limiting (CWE-400)**  
   Der `RateLimitingFilter` zählt die Anzahl der Requests pro Client-IP im 1-Minuten-Fenster. Überschreitet ein Client die Grenze (hier 60), wird HTTP 429 zurückgegeben. Der zentrale Speicher wird regelmäßig geleert, um Speicherlecks zu vermeiden. Eine Alternative wäre die Integration von Bucket4j oder Resilience4j, aber die gezeigte Lösung ist leichtgewichtig und ohne externe Abhängigkeiten.

4. **Fehlerbehandlung**  
   Jede ungültige URL führt zu einer `InvalidUrlException`, die vom `@RestControllerAdvice` in eine aussagekräftige 400-Antwort umgewandelt wird. So erhält der Client keine internen Stack-Traces.

5. **Struktur nach Java-Konventionen**  
   Jede Klasse ist in einer eigenen Datei organisiert, sauber kompilierbar mit den richtigen Imports. Es gibt keine inneren Klassen.

Diese Implementierung erfüllt die Anforderungen gemäß dem "Unvalidated Redirects and Forwards Cheat Sheet" und schützt vor Open Redirect, Input Validation und Abuse."}]

[{"type": "CODE_BLOCK", "language": "java", "content": "// RestTemplateConfig.java
package com.example.config;

import com.example.util.LenientHostnameVerifier;
import org.apache.hc.client5.http.impl.classic.CloseableHttpClient;
import org.apache.hc.client5.http.impl.classic.HttpClients;
import org.apache.hc.client5.http.impl.io.PoolingHttpClientConnectionManagerBuilder;
import org.apache.hc.client5.http.io.HttpClientConnectionManager;
import org.apache.hc.client5.http.ssl.SSLConnectionSocketFactory;
import org.apache.hc.core5.ssl.SSLContexts;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory;
import org.springframework.web.client.RestTemplate;

import javax.net.ssl.SSLContext;
import java.security.KeyManagementException;
import java.security.NoSuchAlgorithmException;

/**
 * Konfiguration des RestTemplate mit sicherer SSL/TLS-Verbindung und flexiblem Hostname-Verifier.
 * Entspricht den Anforderungen:
 * - Strikte TLS-Protokolle (TLS 1.2/1.3)
 * - Starke Cipher Suites (AES-GCM, ChaCha20, ECDHE)
 * - Benutzerdefinierte Hostname-Validierung (toleriert geringe Abweichungen für erlaubte Hosts)
 * - Verwendet Apache HttpClient 5 für bessere Kontrolle.
 */
@Configuration
public class RestTemplateConfig {

    @Bean
    public RestTemplate secureRestTemplate(SSLContext sslContext) {
        // SSLConnectionSocketFactory mit strengen Protokoll- und Cipher-Suites
        String[] supportedProtocols = {"TLSv1.2", "TLSv1.3"};
        String[] supportedCiphers = {
                "TLS_AES_256_GCM_SHA384",
                "TLS_CHACHA20_POLY1305_SHA256",
                "TLS_AES_128_GCM_SHA256",
                "TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384",
                "TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384",
                "TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256",
                "TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256",
                "TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305_SHA256",
                "TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256"
        };

        SSLConnectionSocketFactory sslSocketFactory = new SSLConnectionSocketFactory(
                sslContext,
                supportedProtocols,
                supportedCiphers,
                new LenientHostnameVerifier() // Flexibler Hostname-Verifier
        );

        HttpClientConnectionManager connectionManager = PoolingHttpClientConnectionManagerBuilder.create()
                .setSSLSocketFactory(sslSocketFactory)
                .build();

        CloseableHttpClient httpClient = HttpClients.custom()
                .setConnectionManager(connectionManager)
                .build();

        HttpComponentsClientHttpRequestFactory factory = new HttpComponentsClientHttpRequestFactory(httpClient);
        return new RestTemplate(factory);
    }

    @Bean
    public SSLContext sslContext() throws NoSuchAlgorithmException, KeyManagementException {
        // Standard-Java-TrustStore (vertrauenswürdige CAs) – keine Selbstsignierung erlaubt
        return SSLContexts.createDefault();
    }
}
