### 3. KeyStoreManager.java

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// KeyStoreManager.java
package com.example.encryption.service;

import com.example.encryption.config.EncryptionConfig;
import org.springframework.stereotype.Component;

import javax.crypto.SecretKey;
import javax.crypto.spec.SecretKeySpec;
import java.io.InputStream;
import java.security.KeyStore;

@Component
public class KeyStoreManager {

    private final SecretKey masterKey;

    public KeyStoreManager(EncryptionConfig config) throws Exception {
        KeyStore keyStore = KeyStore.getInstance("JKS");
        try (InputStream is = getClass().getClassLoader().getResourceAsStream(config.getPath())) {
            if (is == null) {
                throw new IllegalStateException("KeyStore not found: " + config.getPath());
            }
            keyStore.load(is, config.getPassword().toCharArray());
        }
        // Schlüssel als SecretKey laden
        masterKey = (SecretKey) keyStore.getKey(config.getAlias(), config.getKeyPassword().toCharArray());
        if (masterKey == null) {
            throw new IllegalStateException("Master key alias not found: " + config.getAlias());
        }
        // Sicherstellen, dass der Schlüssel 256 Bit (32 Bytes) hat
        if (masterKey.getEncoded().length != 32) {
            throw new IllegalStateException("Master key must be 256 bits (32 bytes)");
        }
    }

    public SecretKey getMasterKey() {
        return masterKey;
    }
}
