    public String validate(String userId) {
        if (userId == null || userId.isBlank()) {
            return "default"; // Standardwert für nicht angegebenen userId
        }
        if (!USER_ID_PATTERN.matcher(userId).matches()) {
            throw new InvalidUserIdException("Invalid userId format. Only alphanumeric characters, underscores, and hyphens allowed, max 100 characters.");
