### 6. EncryptionService.java

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// EncryptionService.java
package com.example.encryption.service;

import com.example.encryption.validation.UserIdValidator;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import javax.crypto.*;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.PBEKeySpec;
import javax.crypto.spec.SecretKeySpec;
import java.security.NoSuchAlgorithmException;
import java.security.SecureRandom;
import java.security.spec.InvalidKeySpecException;
import java.util.Base64;

@Service
public class EncryptionService {

    private static final Logger LOGGER = LoggerFactory.getLogger(EncryptionService.class);

    private static final String ALGORITHM = "AES";
    private static final String CIPHER_ALGORITHM = "AES/GCM/NoPadding";
    private static final int KEY_SIZE = 256;
    private static final int TAG_LENGTH = 128; // in bits
    private static final int IV_LENGTH = 12; // 96 bits

    // PBKDF2 Parameter für deterministische Schlüsselableitung
    private static final int PBKDF2_ITERATIONS = 100_000;
    private static final String PBKDF2_ALGORITHM = "PBKDF2WithHmacSHA256";
    private static final int DERIVED_KEY_LENGTH = 256; // bits

    private final KeyStoreManager keyStoreManager;
    private final UserIdValidator userIdValidator;

    public EncryptionService(KeyStoreManager keyStoreManager, UserIdValidator userIdValidator) {
        this.keyStoreManager = keyStoreManager;
        this.userIdValidator = userIdValidator;
    }

    public String encryptText(String plaintext, String rawUserId) {
        // userId validieren und ggf. Default setzen
        String userId = userIdValidator.validate(rawUserId);
        LOGGER.debug("Encrypting text for userId: {}", userId);

        try {
            // 1. Schlüssel für diesen userId ableiten
            SecretKey derivedKey = deriveKey(userId);

            // 2. Zufälligen Nonce (IV) generieren
            byte[] iv = new byte[IV_LENGTH];
            SecureRandom random = new SecureRandom();
            random.nextBytes(iv);

            // 3. Verschlüsseln
            Cipher cipher = Cipher.getInstance(CIPHER_ALGORITHM);
            GCMParameterSpec gcmSpec = new GCMParameterSpec(TAG_LENGTH, iv);
            cipher.init(Cipher.ENCRYPT_MODE, derivedKey, gcmSpec);
            byte[] ciphertext = cipher.doFinal(plaintext.getBytes(java.nio.charset.StandardCharsets.UTF_8));

            // 4. Nonce vor den Chiffretext setzen und Base64-kodieren
            byte[] combined = new byte[IV_LENGTH + ciphertext.length];
            System.arraycopy(iv, 0, combined, 0, IV_LENGTH);
            System.arraycopy(ciphertext, 0, combined, IV_LENGTH, ciphertext.length);
            String encryptedBase64 = Base64.getEncoder().encodeToString(combined);

            LOGGER.info("Encryption successful for userId: {}", userId);
            return encryptedBase64;

        } catch (Exception e) {
            LOGGER.error("Encryption failed for userId: {}", userId, e);
            throw new RuntimeException("Encryption failed", e);
        }
    }

    private SecretKey deriveKey(String userId) throws NoSuchAlgorithmException, InvalidKeySpecException {
        // Master-Key als Passwort
        byte[] masterKeyBytes = keyStoreManager.getMasterKey().getEncoded();
        // Verwende userId als Salt (deterministisch)
        // Salt sollte eigentlich zufällig sein, aber hier für Determinismus userId selbst.
        // Sicherheit: Salt ist bekannt, aber Master-Key nicht.
        PBEKeySpec spec = new PBEKeySpec(
                new String(masterKeyBytes, java.nio.charset.StandardCharsets.ISO_8859_1).toCharArray(),
                userId.getBytes(java.nio.charset.StandardCharsets.UTF_8),
                PBKDF2_ITERATIONS,
                DERIVED_KEY_LENGTH
        );
        SecretKeyFactory factory = SecretKeyFactory.getInstance(PBKDF2_ALGORITHM);
        byte[] derivedBytes = factory.generateSecret(spec).getEncoded();
        return new SecretKeySpec(derivedBytes, 0, derivedBytes.length, ALGORITHM);
    }
}
