### 5. `GlobalExceptionHandler.java` – Zentrale Behandlung von Validierungs‑ und Systemfehlern

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.callback;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.stream.Collectors;

/**
 * Sorgt für konsistente Fehlerantworten und verhindert das Durchsickern
 * von technischen Details (Information Disclosure).
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * Validiert der Controller die Eingabe nicht (z. B. @Valid), wird diese Exception geworfen.
     * Die Antwort enthält nur die zusammengefassten Fehlermeldungen – kein Strack Trace.
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<String> handleValidationExceptions(MethodArgumentNotValidException ex) {
        String errorMessage = ex.getBindingResult().getFieldErrors()
                .stream()
                .map(err -> err.getField() + ": " + err.getDefaultMessage())
                .collect(Collectors.joining(", "));
        return ResponseEntity.badRequest().body("Ungültige Eingabe: " + errorMessage);
    }

    /**
     * Fängt alle anderen (z. B. Datenbank‑) Fehler ab und gibt einen sicheren
     * generischen Fehler zurück – kein SQL‑ oder Stack‑Trace.
     */
    @ExceptionHandler(Exception.class)
    public ResponseEntity<String> handleGeneralErrors(Exception ex) {
        // Loggen des Fehlers für internes Debugging
        // logger.error("Unbehandelter Fehler", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body("Interner Serverfehler");
    }
}
