package de.besecure.example.entity;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.Map;

@Entity
@Table(name = "application_config")
public class ApplicationConfig {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(nullable = false)
    private String defaultRole;

    @Column(nullable = false, precision = 12, scale = 2)
    private BigDecimal maxRefundAmount;

    @ElementCollection
    @CollectionTable(name = "feature_flags", joinColumns = @JoinColumn(name = "config_id"))
    @MapKeyColumn(name = "feature_key")
    @Column(name = "feature_value")
    private Map<String, Boolean> featureFlags;

    @Column(nullable = false)
    private String supportEmail;

    @Column(nullable = false)
    private Boolean maintenanceMode;

    // Konstruktoren, Getter, Setter (hier aus Platzgründen nur Getter/Setter angedeutet)
    public ApplicationConfig() {}

    public ApplicationConfig(String defaultRole, BigDecimal maxRefundAmount,
                             Map<String, Boolean> featureFlags, String supportEmail,
                             Boolean maintenanceMode) {
        this.defaultRole = defaultRole;
        this.maxRefundAmount = maxRefundAmount;
        this.featureFlags = featureFlags;
        this.supportEmail = supportEmail;
        this.maintenanceMode = maintenanceMode;
    }

    // Getter / Setter (bitte vollständig generieren)
    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public String getDefaultRole() { return defaultRole; }
    public void setDefaultRole(String defaultRole) { this.defaultRole = defaultRole; }
    public BigDecimal getMaxRefundAmount() { return maxRefundAmount; }
    public void setMaxRefundAmount(BigDecimal maxRefundAmount) { this.maxRefundAmount = maxRefundAmount; }
    public Map<String, Boolean> getFeatureFlags() { return featureFlags; }
    public void setFeatureFlags(Map<String, Boolean> featureFlags) { this.featureFlags = featureFlags; }
    public String getSupportEmail() { return supportEmail; }
    public void setSupportEmail(String supportEmail) { this.supportEmail = supportEmail; }
    public Boolean getMaintenanceMode() { return maintenanceMode; }
    public void setMaintenanceMode(Boolean maintenanceMode) { this.maintenanceMode = maintenanceMode; }
}
