### 6. Service `ApplicationConfigService.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ApplicationConfigService.java
package de.besecure.example.service;

import de.besecure.example.dto.InitialConfigRequest;
import de.besecure.example.entity.ApplicationConfig;
import de.besecure.example.repository.ApplicationConfigRepository;
import de.besecure.example.util.Sanitizer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.HashMap;
import java.util.Map;

@Service
public class ApplicationConfigService {

    private static final Logger log = LoggerFactory.getLogger(ApplicationConfigService.class);

    private final ApplicationConfigRepository repository;

    public ApplicationConfigService(ApplicationConfigRepository repository) {
        this.repository = repository;
    }

    /**
     * Speichert die initiale Konfiguration nur, wenn noch keine existiert.
     * Fehlende Felder werden nicht überschrieben – hier wird jedoch die vollständige
     * Konfiguration aus dem Request erwartet (Validierung stellt sicher, dass alle Felder vorhanden sind).
     * Falls später eine partielle Aktualisierung gewünscht ist, könnte man die Logik erweitern.
     */
    @Transactional
    public ApplicationConfig initializeConfig(InitialConfigRequest request) {
        // Prüfen, ob bereits eine Konfiguration existiert
        if (repository.count() > 0) {
            throw new IllegalStateException("Initial configuration has already been set. Use PATCH endpoint for updates.");
        }

        // Sanitisierung aller String-Felder
        String safeDefaultRole = Sanitizer.sanitize(request.getDefaultRole());
        String safeSupportEmail = Sanitizer.sanitize(request.getSupportEmail());
        Map<String, Boolean> safeFeatureFlags = sanitizeFeatureFlags(request.getFeatureFlags());

        ApplicationConfig config = new ApplicationConfig(
                safeDefaultRole,
                request.getMaxRefundAmount(),
                safeFeatureFlags,
                safeSupportEmail,
                request.getMaintenanceMode()
        );

        ApplicationConfig saved = repository.save(config);
        log.info("Initial application configuration created with id={} by admin", saved.getId());
        return saved;
    }

    /**
     * Sanitisiert die Schlüssel der Feature-Flags (Werte sind Boolean und daher sicher).
     */
    private Map<String, Boolean> sanitizeFeatureFlags(Map<String, Boolean> flags) {
        Map<String, Boolean> sanitized = new HashMap<>();
        for (Map.Entry<String, Boolean> entry : flags.entrySet()) {
            sanitized.put(Sanitizer.sanitize(entry.getKey()), entry.getValue());
        }
        return sanitized;
    }
}
", "fileName": "Component_6", "vulnerbility": null}, {"type": "TEXT", "text": "

### 7. Controller `InitialConfigController.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// InitialConfigController.java
package de.besecure.example.controller;

import de.besecure.example.dto.InitialConfigRequest;
import de.besecure.example.dto.InitialConfigResponse;
import de.besecure.example.entity.ApplicationConfig;
import de.besecure.example.service.ApplicationConfigService;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/admin")
public class InitialConfigController {

    private final ApplicationConfigService configService;

    public InitialConfigController(ApplicationConfigService configService) {
        this.configService = configService;
    }

    /**
     * POST /api/admin/initial-config
     * Nur Admin-Benutzer dürfen diese Operation ausführen.
     * Der Endpoint erwartet JSON und validiert den Body.
     */
    @PostMapping(value = "/initial-config", consumes = MediaType.APPLICATION_JSON_VALUE, produces = MediaType.APPLICATION_JSON_VALUE)
    @PreAuthorize("hasRole('ADMIN')")
    public ResponseEntity<InitialConfigResponse> initializeConfig(@Valid @RequestBody InitialConfigRequest request) {
        // Service wirft IllegalStateException falls bereits initialisiert
        ApplicationConfig config = configService.initializeConfig(request);
        return ResponseEntity.status(HttpStatus.CREATED)
                .body(new InitialConfigResponse(config.getId(), "Configuration created"));
    }
}
