import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.stream.Collectors;

@RestControllerAdvice
public class GlobalExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    // 400 – Validierungsfehler (Bean Validation)
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Object> handleValidationErrors(MethodArgumentNotValidException ex) {
        String errors = ex.getBindingResult().getFieldErrors()
                .stream()
                .map(err -> err.getField() + ": " + err.getDefaultMessage())
                .collect(Collectors.joining(", "));
        log.warn("Validation failed: {}", errors);
        return ResponseEntity.badRequest().body(new InitialConfigResponse(null, "Validation failed: " + errors));
    }

    // 400 – Fehlerhafte JSON-Struktur (z.B. falscher Typ)
    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<Object> handleMalformedJson(HttpMessageNotReadableException ex) {
        log.warn("Malformed JSON: {}", ex.getMessage());
        return ResponseEntity.badRequest().body(new InitialConfigResponse(null, "Invalid request body"));
    }

    // 405 – Nicht erlaubte HTTP-Methode
    @ExceptionHandler(HttpRequestMethodNotSupportedException.class)
    public ResponseEntity<Object> handleMethodNotAllowed(HttpRequestMethodNotSupportedException ex) {
        return ResponseEntity.status(HttpStatus.METHOD_NOT_ALLOWED)
                .body(new InitialConfigResponse(null, "HTTP method not supported"));
    }

    // 415 – Nicht unterstützter Media Type
    @ExceptionHandler(HttpMediaTypeNotSupportedException.class)
    public ResponseEntity<Object> handleUnsupportedMediaType(HttpMediaTypeNotSupportedException ex) {
        return ResponseEntity.status(HttpStatus.UNSUPPORTED_MEDIA_TYPE)
                .body(new InitialConfigResponse(null, "Only application/json is accepted"));
    }

    // 409 – Konfiguration bereits vorhanden (IllegalStateException aus Service)
    @ExceptionHandler(IllegalStateException.class)
    public ResponseEntity<Object> handleAlreadyInitialized(IllegalStateException ex) {
        log.warn("Attempt to re-initialize config: {}", ex.getMessage());
        return ResponseEntity.status(HttpStatus.CONFLICT)
                .body(new InitialConfigResponse(null, "Initial configuration already exists"));
    }

    // 500 – Allgemeiner Serverfehler (keine internen Details preisgeben)
    @ExceptionHandler(Exception.class)
    public ResponseEntity<Object> handleAllExceptions(Exception ex) {
        log.error("Unexpected error", ex);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(new InitialConfigResponse(null, "An internal error occurred"));
    }
}
