### `Cart.java` – Warenkorb mit defensiver Kopie

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// Cart.java
package com.example.cart;

import com.fasterxml.jackson.databind.annotation.JsonDeserialize;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;

/**
 * Mutable-freie Liste von CartItems. Der Konstruktor erstellt eine defensive Kopie.
 * Die Klasse ist für Jackson mit einem benutzerdefinierten Deserializer annotiert.
 */
@JsonDeserialize(using = CartDeserializer.class)
public final class Cart {
    private final List<CartItem> items;

    /**
     * @param items  Nicht-null, nicht-null-Entries – wird defensiv kopiert.
     */
    public Cart(List<CartItem> items) {
        // CERT SER06-J: Verteidigungskopie der Liste und jedes Elements (CartItem ist bereits immutable)
        Objects.requireNonNull(items, "items must not be null");
        List<CartItem> copy = new ArrayList<>(items.size());
        for (CartItem item : items) {
            Objects.requireNonNull(item, "item must not be null");
            copy.add(item);  // CartItem ist selbst unveränderlich, daher keine tiefe Kopie nötig
        }
        this.items = Collections.unmodifiableList(copy);  // unmodifiable verhindert nachträgliche Änderungen
    }

    public List<CartItem> getItems() {
        // Gibt eine Kopie zurück, damit der Aufrufer die innere Liste nicht ändern kann
        return new ArrayList<>(items);
    }

    // Wird vom Deserializer nach der Validierung benötigt
    List<CartItem> internalItems() { return items; }
}
