### `CartDeserializer.java` – Benutzerdefinierter Jackson‑Deserializer

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartDeserializer.java
package com.example.cart;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.TreeNode;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

/**
 * Eigenständiger Deserializer, der JSON-Struktur validiert und nur Cart aus den erlaubten Feldern erzeugt.
 * Verhindert unerwünschte Felder und stellt Invarianten sicher (CERT SER07-J).
 */
public class CartDeserializer extends JsonDeserializer<Cart> {

    @Override
    public Cart deserialize(JsonParser p, DeserializationContext ctxt) throws IOException {
        ObjectMapper mapper = (ObjectMapper) p.getCodec();
        JsonNode root = mapper.readTree(p);

        // Erwarte ein Objekt mit einem "items"-Array
        if (!root.isObject()) {
            throw new JsonProcessingException("Cart must be a JSON object") {};
        }
        JsonNode itemsNode = root.get("items");
        if (itemsNode == null || !itemsNode.isArray()) {
            throw new JsonProcessingException("Missing or invalid 'items' array") {};
        }

        ArrayNode arrayNode = (ArrayNode) itemsNode;
        List<CartItem> items = new ArrayList<>(arrayNode.size());
        Iterator<JsonNode> it = arrayNode.elements();
        while (it.hasNext()) {
            JsonNode itemNode = it.next();

            // Einzelne CartItem-Objekte validieren
            if (!itemNode.isObject()) {
                throw new JsonProcessingException("Each item must be a JSON object") {};
            }
            JsonNode articleIdNode = itemNode.get("articleId");
            JsonNode quantityNode = itemNode.get("quantity");
            if (articleIdNode == null || !articleIdNode.canConvertToInt()
                || quantityNode == null || !quantityNode.canConvertToInt()) {
                throw new JsonProcessingException("Each item must have valid 'articleId' (int) and 'quantity' (int)") {};
            }
            int articleId = articleIdNode.asInt();
            int quantity   = quantityNode.asInt();

            // Invarianten-Prüfung analog zum Konstruktor (SER07-J)
            if (articleId <= 0) {
                throw new IllegalArgumentException("articleId must be positive");
            }
            if (quantity < 0) {
                throw new IllegalArgumentException("quantity must be non-negative");
            }

            // Erzeuge CartItem über den sicheren Konstruktor
            items.add(new CartItem(articleId, quantity));
        }

        // Erzeuge Cart – der Konstruktor erstellt eine defensive Kopie (SER06-J)
        return new Cart(items);
    }
}
