### `CartResponse.java` – Antwort‑DTO (ohne sensible Daten)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartResponse.java
package com.example.cart;

import java.util.List;
import java.util.Objects;

/**
 * Antwortobjekt: gibt nur die Artikel (mit articleId und quantity) sowie die Gesamtsumme zurück.
 * Enthält keine Datenbank- oder Systeminformationen.
 */
public final class CartResponse {
    private final List<CartItem> items;
    private final double totalSum;

    public CartResponse(List<CartItem> items, double totalSum) {
        this.items = List.copyOf(items); // unmodifiable, keine Referenz auf Original
        this.totalSum = totalSum;
    }

    public List<CartItem> getItems()    { return items; }
    public double      getTotalSum()   { return totalSum; }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (!(o instanceof CartResponse that)) return false;
        return Double.compare(totalSum, that.totalSum) == 0 && items.equals(that.items);
    }

    @Override
    public int hashCode() { return Objects.hash(items, totalSum); }
}
