### `ArticleService.java` – Service zum Laden der Artikelpreise

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// ArticleService.java
package com.example.cart;

import org.springframework.stereotype.Service;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Simulierter Service, der Artikelinformationen aus der Datenbank lädt.
 * In der Praxis würde hier ein Repository verwendet.
 */
@Service
public class ArticleService {

    // Simulierte DB – Artikel-ID -> Preis
    private static final Map<Integer, Double> ARTICLE_PRICES = new HashMap<>();
    static {
        ARTICLE_PRICES.put(1, 12.99);
        ARTICLE_PRICES.put(2,  7.50);
        ARTICLE_PRICES.put(3, 24.99);
        // ...
    }

    /**
     * Lädt die Preise zu den angegebenen Artikel-IDs.
     *
     * @param articleIds Liste der IDs, darf nicht null sein
     * @return Map articleId -> price, unveränderlich
     * @throws IllegalArgumentException wenn eine unbekannte ID vorkommt
     */
    public Map<Integer, Double> getArticlePrices(List<Integer> articleIds) {
        // Defensive Kopie der Eingabe
        List<Integer> ids = List.copyOf(articleIds);
        Map<Integer, Double> result = new HashMap<>();
        for (int id : ids) {
            Double price = ARTICLE_PRICES.get(id);
            if (price == null) {
                throw new IllegalArgumentException("Unknown article id: " + id);
            }
            result.put(id, price);
        }
        return Map.copyOf(result);
    }
}
