### `CartController.java` – REST‑Endpoint

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CartController.java
package com.example.cart;

import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Base64;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/cart")
public class CartController {

    private final ArticleService articleService;
    private final SecureObjectMapper objectMapper;  // konfigurierte Instanz (siehe unten)

    public CartController(ArticleService articleService, SecureObjectMapper objectMapper) {
        this.articleService = articleService;
        this.objectMapper = objectMapper;
    }

    @PostMapping(consumes = MediaType.TEXT_PLAIN_VALUE, produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<CartResponse> loadCart(@RequestBody String encodedCart) {
        // 1. Base64 dekodieren
        byte[] decodedBytes = Base64.getDecoder().decode(encodedCart);

        // 2. Sicher deserialisieren (eigener Deserializer wird verwendet)
        Cart cart = objectMapper.readValue(decodedBytes, Cart.class);

        // 3. Artikel-IDs extrahieren (über defensive Kopie, da getItems() Kopie zurückgibt)
        List<Integer> articleIds = cart.getItems().stream()
                .map(CartItem::getArticleId)
                .collect(Collectors.toList());

        // 4. Preise aus DB laden
        Map<Integer, Double> priceMap = articleService.getArticlePrices(articleIds);

        // 5. Gesamtsumme berechnen
        double totalSum = cart.getItems().stream()
                .mapToDouble(item -> priceMap.get(item.getArticleId()) * item.getQuantity())
                .sum();

        // 6. Antwort erstellen (mit Sicherheitsheadern)
        CartResponse body = new CartResponse(cart.getItems(), totalSum);
        HttpHeaders headers = new HttpHeaders();
        headers.add("X-Content-Type-Options", "nosniff");
        headers.add("X-Frame-Options", "DENY");
        headers.add("X-XSS-Protection", "1; mode=block");
        headers.add("Cache-Control", "no-store");
        headers.add("Content-Security-Policy", "default-src 'none'");

        return ResponseEntity.ok()
                .headers(headers)
                .body(body);
    }
}
