### `SecureObjectMapper.java` – Konfigurierte ObjectMapper‑Bean

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureObjectMapper.java
package com.example.cart;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.module.SimpleModule;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Stellt eine abgesicherte ObjectMapper-Instanz bereit, die nur den erlaubten Deserializer verwendet.
 */
@Configuration
public class SecureObjectMapper {

    @Bean
    public ObjectMapper objectMapper() {
        ObjectMapper mapper = new ObjectMapper();

        // Sicherheitskonfiguration
        mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, true);
        mapper.configure(DeserializationFeature.FAIL_ON_NULL_FOR_PRIMITIVES, true);
        // Niemals DefaultTyping aktivieren (CWE-502)
        mapper.disableDefaultTyping();

        // Eigenen Modul mit CartDeserializer registrieren
        SimpleModule module = new SimpleModule();
        module.addDeserializer(Cart.class, new CartDeserializer());
        mapper.registerModule(module);

        return mapper;
    }
}
", "fileName": "Component_6", "vulnerbility": null}, {"type": "TEXT", "text": "

