### 2. Validation Service – `RedirectValidationService.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RedirectValidationService.java
package com.example.redirect;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.net.InetAddress;
import java.net.URI;
import java.net.UnknownHostException;
import java.util.List;
import java.util.stream.Collectors;

/**
 * Validates and sanitizes redirect URLs.
 * Uses a whitelist of allowed hosts and blocks private IP addresses.
 */
@Service
public class RedirectValidationService {

    private static final Logger logger = LoggerFactory.getLogger(RedirectValidationService.class);
    private final List<String> allowedHosts;

    public RedirectValidationService(RedirectProperties properties) {
        // Normalize whitelist (lowercase, trimmed)
        this.allowedHosts = properties.getAllowedHosts().stream()
                .map(String::trim)
                .map(String::toLowerCase)
                .collect(Collectors.toList());
    }

    /**
     * Validates the given URL.
     * Returns the sanitized URL if valid, null otherwise.
     */
    public String validateAndSanitize(String url) {
        if (url == null || url.trim().isEmpty()) {
            return null;
        }

        String trimmed = url.trim();

        // Only allow http and https schemes
        if (!trimmed.startsWith("http://") && !trimmed.startsWith("https://")) {
            logger.warn("Invalid scheme in URL: {}", trimmed);
            return null;
        }

        try {
            URI uri = new URI(trimmed);
            String host = uri.getHost();

            if (host == null) {
                logger.warn("URL without host: {}", trimmed);
                return null;
            }

            // Check against whitelist
            boolean hostAllowed = allowedHosts.stream()
                    .anyMatch(allowed -> host.equalsIgnoreCase(allowed) ||
                            host.endsWith("." + allowed));  // allow subdomains
            if (!hostAllowed) {
                logger.warn("Host '{}' not in whitelist", host);
                return null;
            }

            // Block private IP addresses (e.g., 127.0.0.1, 10.x.x.x, 192.168.x.x)
            if (isPrivateIp(host)) {
                logger.warn("Private IP address blocked: {}", host);
                return null;
            }

            // Block user info (credentials) in URL
            if (uri.getUserInfo() != null) {
                logger.warn("User info present in URL: {}", trimmed);
                return null;
            }

            // Return the sanitized URL (already safe by checks)
            return trimmed;

        } catch (Exception e) {
            logger.warn("Malformed URL: {}", trimmed, e);
            return null;
        }
    }

    /**
     * Checks if the given host string is a private IP address.
     */
    private boolean isPrivateIp(String host) {
        try {
            InetAddress inet = InetAddress.getByName(host);
            return inet.isSiteLocalAddress() || inet.isLoopbackAddress() || inet.isLinkLocalAddress();
        } catch (UnknownHostException e) {
            // If we can't resolve, assume it's not a private IP (e.g., hostname)
            return false;
        }
    }
}
