### 2. Sichere DocumentBuilderFactory: `SecureDocumentBuilderFactory.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecureDocumentBuilderFactory.java
package com.example.xml.config;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

/**
 * Stellt einen XXE-sicheren DocumentBuilder bereit.
 * Alle gefährlichen Features werden deaktiviert (DTD, externe Entitäten, XInclude).
 */
@Component
public class SecureDocumentBuilderFactory {

    private static final Logger logger = LoggerFactory.getLogger(SecureDocumentBuilderFactory.class);

    private final DocumentBuilderFactory dbf;

    public SecureDocumentBuilderFactory() throws ParserConfigurationException {
        // Sicherheitshärtung: Standard-Secure-Factory verwenden (Java 9+)
        this.dbf = DocumentBuilderFactory.newDefaultInstance();
        applySecuritySettings();
    }

    private void applySecuritySettings() throws ParserConfigurationException {
        // 1. DOCTYPE komplett verbieten (primäre Verteidigung)
        setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);

        // 2. Externe allgemeine Entitäten deaktivieren (zusätzlich)
        setFeature("http://xml.org/sax/features/external-general-entities", false);

        // 3. Externe Parameter-Entitäten deaktivieren
        setFeature("http://xml.org/sax/features/external-parameter-entities", false);

        // 4. Externes DTD-Laden verhindern
        setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // 5. Sicheren Verarbeitungsmodus (verhindert Entity Expansion DoS)
        dbf.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // 6. DTD- und Schema-Zugriff auf leer setzen (Java 8+)
        dbf.setFeature(XMLConstants.ACCESS_EXTERNAL_DTD, "");
        dbf.setFeature(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        // 7. XInclude deaktivieren (kann Dateien einschleusen)
        dbf.setXIncludeAware(false);

        // 8. Keine Erweiterung von Entity-Referenzen (sollte durch 1–4 bereits verhindert)
        dbf.setExpandEntityReferences(false);
    }

    private void setFeature(String feature, boolean value) throws ParserConfigurationException {
        try {
            dbf.setFeature(feature, value);
        } catch (ParserConfigurationException e) {
            // Kritische Features müssen unterstützt werden – sonst Fehler weiterwerfen
            logger.error("Feature {} wird von diesem XML-Prozessor nicht unterstützt und kann nicht deaktiviert werden: {}", feature, e.getMessage());
            throw e;
        }
    }

    public DocumentBuilder newDocumentBuilder() throws ParserConfigurationException {
        DocumentBuilder builder = dbf.newDocumentBuilder();
        // NoOp-EntityResolver verhindert auch bei versehentlich aktivierten DTDs die Auflösung
        builder.setEntityResolver((publicId, systemId) -> new org.xml.sax.InputSource(new java.io.StringReader("")));
        return builder;
    }
}
", "fileName": "Component_1", "vulnerbility": null}, {"type": "TEXT", "text": "

