### 3. Whitelist-Validator: `XmlWhitelistValidator.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlWhitelistValidator.java
package com.example.xml.validation;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;
import java.util.Set;

/**
 * Stellt sicher, dass das XML-Dokument nur erlaubte Elemente und Attribute enthält.
 * Dies verhindert CWE-434 (Upload gefährlicher Dateien) und zusätzliche Eindämmung von XXE.
 */
public class XmlWhitelistValidator {

    // Erlaubte Tags und ihre erlaubten Attribute (hier: keine Attribute erlaubt)
    private static final Set<String> ALLOWED_TAGS = Set.of("person", "name", "age");
    private static final Set<String> ALLOWED_ATTRIBUTES = Set.of(); // keine Attribute erlaubt

    /**
     * Validiert das gesamte Dokument gegen die Whitelist.
     * @throws IllegalArgumentException wenn ein nicht erlaubtes Tag oder Attribut gefunden wird.
     */
    public static void validate(Document document) {
        traverseAndValidate(document.getDocumentElement());
    }

    private static void traverseAndValidate(Element element) {
        // 1. Tag-Name prüfen
        if (!ALLOWED_TAGS.contains(element.getTagName())) {
            throw new IllegalArgumentException("Unerlaubtes XML-Tag: " + element.getTagName());
        }

        // 2. Attribute prüfen
        for (int i = 0; i < element.getAttributes().getLength(); i++) {
            Node attr = element.getAttributes().item(i);
            if (!ALLOWED_ATTRIBUTES.contains(attr.getNodeName())) {
                throw new IllegalArgumentException("Unerlaubtes Attribut: " + attr.getNodeName());
            }
        }

        // 3. Kinder rekursiv prüfen
        NodeList children = element.getChildNodes();
        for (int i = 0; i < children.getLength(); i++) {
            Node child = children.item(i);
            if (child.getNodeType() == Node.ELEMENT_NODE) {
                traverseAndValidate((Element) child);
            }
        }
    }
}
