### 5. Service: `XmlService.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlService.java
package com.example.xml.service;

import com.example.xml.Person;
import com.example.xml.config.SecureDocumentBuilderFactory;
import com.example.xml.exception.XmlProcessingException;
import com.example.xml.validation.XmlWhitelistValidator;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

import javax.xml.bind.JAXBContext;
import javax.xml.bind.JAXBException;
import javax.xml.bind.Unmarshaller;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.ParserConfigurationException;
import java.io.IOException;
import java.io.StringReader;

@Service
public class XmlService {

    private final SecureDocumentBuilderFactory secureFactory;
    private final JAXBContext jaxbContext;
    private final ObjectMapper objectMapper;

    public XmlService(SecureDocumentBuilderFactory secureFactory, JAXBContext jaxbContext, ObjectMapper objectMapper) {
        this.secureFactory = secureFactory;
        this.jaxbContext = jaxbContext;
        this.objectMapper = objectMapper;
    }

    public String processXml(String xmlData) {
        try {
            // 1. Dokument sicher parsen (XXE geschützt)
            DocumentBuilder builder = secureFactory.newDocumentBuilder();
            Document document = builder.parse(new InputSource(new StringReader(xmlData)));

            // 2. Whitelist-Validierung (CWE-434)
            XmlWhitelistValidator.validate(document);

            // 3. JAXB-Unmarshalling (verwendet das bereits geparste Document)
            Unmarshaller unmarshaller = jaxbContext.createUnmarshaller();
            Person person = unmarshaller.unmarshal(document, Person.class).getValue();

            // 4. Optional: Geschäftslogik-Validierung (z.B. Alter > 0)
            if (person.getAge() <= 0) {
                throw new XmlProcessingException("Ungültiges Alter: muss größer 0 sein");
            }

            // 5. Als JSON ausgeben
            return objectMapper.writeValueAsString(person);

        } catch (SAXException | IOException | ParserConfigurationException e) {
            throw new XmlProcessingException("Fehler beim XML-Parsing: " + e.getMessage(), e);
        } catch (JAXBException e) {
            throw new XmlProcessingException("Fehler beim JAXB-Unmarshalling: " + e.getMessage(), e);
        }
    }
}
", "fileName": "Component_4", "vulnerbility": null}, {"type": "TEXT", "text": "

