### 6. Controller: `XmlController.java`

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlController.java
package com.example.xml.controller;

import com.example.xml.service.XmlService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/xml")
public class XmlController {

    private final XmlService xmlService;

    @Autowired
    public XmlController(XmlService xmlService) {
        this.xmlService = xmlService;
    }

    @PostMapping(consumes = "application/xml", produces = "application/json")
    public ResponseEntity<String> processXml(@RequestBody String xmlData) {
        try {
            String jsonResult = xmlService.processXml(xmlData);
            return ResponseEntity.ok(jsonResult);
        } catch (Exception e) {
            // Sicherheitsrelevante Details nicht ausliefern
            return ResponseEntity.badRequest().body("Verarbeitung fehlgeschlagen: " + e.getMessage());
        }
    }
}
