### 3. CustomerService.java – Geschäftslogik mit XXE-sicherer XML-Verarbeitung

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// CustomerService.java
package com.example.demo.service;

import com.example.demo.model.Customer;
import com.example.demo.util.XmlSecureParser;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.io.Resource;
import org.springframework.stereotype.Service;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import org.xml.sax.SAXException;

import javax.xml.namespace.QName;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.transform.stream.StreamSource;
import javax.xml.validation.Schema;
import javax.xml.validation.SchemaFactory;
import javax.xml.validation.Validator;
import javax.xml.xpath.XPath;
import javax.xml.xpath.XPathConstants;
import javax.xml.xpath.XPathExpressionException;
import javax.xml.xpath.XPathFactory;
import javax.xml.xpath.XPathVariableResolver;
import java.io.IOException;
import java.io.InputStream;

@Service
public class CustomerService {

    private static final Logger log = LoggerFactory.getLogger(CustomerService.class);

    private final Resource customerXmlResource;
    private final Resource customerXsdResource;

    // Whitelist für zulässige Zeichen in Kundennamen (zur zusätzlichen Validierung)
    private static final String NAME_PATTERN = "^[a-zA-Z0-9 .\\-_]+$";

    public CustomerService(@Value("classpath:customers.xml") Resource customerXmlResource,
                           @Value("classpath:customers.xsd") Resource customerXsdResource) {
        this.customerXmlResource = customerXmlResource;
        this.customerXsdResource = customerXsdResource;
    }

    /**
     * Sucht in der XML-Datei nach einem Kunden mit dem angegebenen Namen.
     *
     * @param name  Gesuchter Kundenname
     * @return      Gefundener Kunde
     * @throws CustomerNotFoundException wenn kein Kunde mit diesem Namen existiert
     */
    public Customer findByName(String name) {
        // 1. Eingabevalidierung: Nur erlaubte Zeichen akzeptieren
        if (name == null || !name.matches(NAME_PATTERN)) {
            log.warn("Invalid customer name input: {}", name);
            throw new IllegalArgumentException("Name contains invalid characters");
        }

        // 2. XXE-sicheren DocumentBuilder aus der Utility-Klasse holen
        DocumentBuilder builder = XmlSecureParser.newDocumentBuilder();

        // 3. XML-Datei als InputStream öffnen
        try (InputStream xmlStream = customerXmlResource.getInputStream()) {

            // 4. Vor dem Parsen: Validierung gegen das XSD-Schema (ohne externe DTDs)
            validateAgainstXsd(xmlStream);

            // 5. Erneutes Einlesen für das eigentliche Parsen (Stream kann nicht zweimal gelesen werden)
            try (InputStream xmlStream2 = customerXmlResource.getInputStream()) {

                // 6. Dokument parsen
                Document document = builder.parse(xmlStream2);

                // 7. XPath mit parametrisierter Abfrage (verhindert XPath-Injection)
                XPath xPath = XPathFactory.newInstance().newXPath();
                xPath.setXPathVariableResolver(new XPathVariableResolver() {
                    @Override
                    public Object resolveVariable(QName variableName) {
                        if ("name".equals(variableName.getLocalPart())) {
                            return name; // Variable $name wird durch den eingegebenen Wert ersetzt
                        }
                        return null;
                    }
                });

                String xpathExpression = "/customers/customer[name=$name]";
                NodeList nodes = (NodeList) xPath.evaluate(xpathExpression, document, XPathConstants.NODESET);

                if (nodes.getLength() > 0) {
                    // 8. Das erste passende Element in ein Customer-Objekt umwandeln
                    return mapNodeToCustomer(nodes.item(0));
                } else {
                    throw new CustomerNotFoundException("Customer with name '" + name + "' not found");
                }
            }

        } catch (IOException | SAXException | XPathExpressionException e) {
            log.error("Error processing XML: {}", e.getMessage(), e);
            throw new RuntimeException("Failed to retrieve customer data", e);
        }
    }

    /**
     * Validiert den XML-Stream gegen das hinterlegte XSD-Schema.
     * Dabei werden externe DTDs und externe Schemas deaktiviert, um XXE zu verhindern.
     */
    private void validateAgainstXsd(InputStream xmlStream) throws SAXException, IOException {
        // SchemaFactory sicher konfigurieren
        SchemaFactory schemaFactory = SchemaFactory.newInstance("http://www.w3.org/2001/XMLSchema");
        schemaFactory.setProperty(javax.xml.XMLConstants.ACCESS_EXTERNAL_DTD, "");
        schemaFactory.setProperty(javax.xml.XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        Schema schema = schemaFactory.newSchema(customerXsdResource.getURL());
        Validator validator = schema.newValidator();
        validator.setProperty(javax.xml.XMLConstants.ACCESS_EXTERNAL_DTD, "");
        validator.setProperty(javax.xml.XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");

        // Validierung durchführen
        validator.validate(new StreamSource(xmlStream));
    }

    /**
     * Konvertiert ein DOM-Element (customer) in ein Customer-Objekt.
     */
    private Customer mapNodeToCustomer(org.w3c.dom.Node node) {
        org.w3c.dom.Element element = (org.w3c.dom.Element) node;

        int id = Integer.parseInt(element.getElementsByTagName("id").item(0).getTextContent());
        String name = element.getElementsByTagName("name").item(0).getTextContent();
        String email = element.getElementsByTagName("email").item(0).getTextContent();

        return new Customer(id, name, email);
    }
}
