### 4. XmlSecureParser.java – XXE-sichere Parser-Factory

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// XmlSecureParser.java
package com.example.demo.util;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.xml.sax.SAXException;

import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;

/**
 * Zentrale Factory für <code>DocumentBuilder</code>-Instanzen,
 * die nach den OWASP-Empfehlungen gegen XXE gehärtet ist.
 */
public final class XmlSecureParser {

    private static final Logger log = LoggerFactory.getLogger(XmlSecureParser.class);

    private XmlSecureParser() {
        throw new UnsupportedOperationException("Utility class");
    }

    /**
     * Erzeugt einen <code>DocumentBuilder</code> mit maximaler XXE-Prävention.
     *
     * @return gesicherter DocumentBuilder
     * @throws RuntimeException wenn die Konfiguration fehlschlägt (z. B. Feature nicht unterstützt)
     */
    public static DocumentBuilder newDocumentBuilder() {
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();

        // Primäre Verteidigung: DTDs verbieten – falls nicht unterstützt, wird eine Exception geworfen
        try {
            dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
        } catch (ParserConfigurationException e) {
            throw new RuntimeException("XML parser does not support disabling DOCTYPE declarations. " +
                    "XXE prevention is not possible with this parser.", e);
        }

        // Externe allgemeine Entitäten deaktivieren (zusätzliche Sicherheit)
        setFeature(dbf, "http://xml.org/sax/features/external-general-entities", false);

        // Externe Parameter-Entitäten deaktivieren (zusätzliche Sicherheit)
        setFeature(dbf, "http://xml.org/sax/features/external-parameter-entities", false);

        // Externes DTD-Laden deaktivieren
        setFeature(dbf, "http://apache.org/xml/features/nonvalidating/load-external-dtd", false);

        // Sichere Verarbeitung (FSP) aktivieren
        setFeature(dbf, XMLConstants.FEATURE_SECURE_PROCESSING, true);

        // XInclude deaktivieren
        dbf.setXIncludeAware(false);

        // Zusätzliche Kontrolle über externe Ressourcen (Java 8+)
        try {
            dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
            dbf.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
        } catch (IllegalArgumentException e) {
            // Nicht kritisch, da DOCTYPE bereits verboten ist
            log.debug("Attribute ACCESS_EXTERNAL_DTD/SCHEMA not supported by this parser. DOCTYPE is already disabled.");
        }

        // Namespace-Awareness (für XPath und Schema) aktivieren
        dbf.setNamespaceAware(true);

        try {
            return dbf.newDocumentBuilder();
        } catch (ParserConfigurationException e) {
            log.error("Failed to create DocumentBuilder: {}", e.getMessage(), e);
            throw new RuntimeException("XML parser configuration error", e);
        }
    }

    /**
     * Hilfsmethode zum Setzen eines Features mit try/catch, damit
     * nicht unterstützte Features den restlichen Aufbau nicht blockieren.
     * WARNUNG: Diese Methode darf nur für sekundäre Features verwendet werden,
     * nicht für das primäre "disallow-doctype-decl".
     */
    private static void setFeature(DocumentBuilderFactory dbf, String feature, boolean value) {
        try {
            dbf.setFeature(feature, value);
        } catch (ParserConfigurationException e) {
            log.warn("Feature '{}' is not supported by the XML processor. XXE protection may be incomplete.", feature);
        }
    }
}
