## 1. Controller

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlFetchController.java
package com.example.secureurlfetch.controller;

import com.example.secureurlfetch.service.UrlFetchService;
import com.example.secureurlfetch.validation.UrlValidationUtils;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api")
public class UrlFetchController {

    private final UrlFetchService urlFetchService;

    @Autowired
    public UrlFetchController(UrlFetchService urlFetchService) {
        this.urlFetchService = urlFetchService;
    }

    @GetMapping("/fetch")
    @PreAuthorize("hasRole('USER')")
    public ResponseEntity<String> fetchUrl(@RequestParam("url") String url) {
        // 1. Strenge URL-Validierung (SSRF-Prävention)
        UrlValidationUtils.validateUrl(url);

        // 2. HTTP-Aufruf mit Fehlerbehandlung
        String content = urlFetchService.fetchUrlContent(url);

        // 3. Rückgabe als Plain Text (kein Inline-Scripting, Content-Type text/plain)
        return ResponseEntity.ok()
                .contentType(MediaType.TEXT_PLAIN)
                .body(content);
    }
}
