## 3. Service

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// UrlFetchService.java
package com.example.secureurlfetch.service;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import java.net.MalformedURLException;
import java.net.URI;
import java.net.URL;
import java.util.List;

@Service
public class UrlFetchService {

    // Whitelist erlaubter Zielhosts – in der Praxis aus der Konfiguration laden
    private static final List<String> ALLOWED_HOSTS = List.of("api.example.com", "trusted.example.org");

    private final RestTemplate restTemplate;

    public UrlFetchService() {
        this.restTemplate = new RestTemplate();
    }

    /**
     * Ruft den Inhalt der angegebenen URL ab.
     * Die URL wird streng validiert: Nur erlaubte Hosts dürfen verwendet werden,
     * um Server-Side Request Forgery (SSRF) zu verhindern.
     *
     * @param url Eingabe-URL (muss vollständig und korrekt sein)
     * @return Inhalt als String
     * @throws IllegalArgumentException bei ungültigem URL-Format
     * @throws SecurityException        wenn der Host nicht in der Whitelist ist
     * @throws UrlFetchException        bei Fehlern beim Abruf
     */
    public String fetchUrlContent(String url) {
        URL parsedUrl;
        try {
            parsedUrl = new URL(url);
        } catch (MalformedURLException e) {
            throw new IllegalArgumentException("Ungültiges URL-Format", e);
        }

        // Host validieren
        String host = parsedUrl.getHost();
        if (host == null || !ALLOWED_HOSTS.contains(host)) {
            throw new SecurityException("Zugriff auf den angegebenen Host ist nicht erlaubt");
        }

        try {
            ResponseEntity<String> response = restTemplate.getForEntity(parsedUrl.toURI(), String.class);
            if (response.getStatusCode() != HttpStatus.OK) {
                throw new UrlFetchException("Der entfernte Server antwortete mit Fehler");
            }
            return response.getBody();
        } catch (RestClientException | URISyntaxException e) {
            // CWE-209: Keine sensiblen Informationen preisgeben
            throw new UrlFetchException("Fehler beim Abrufen der URL");
        }
    }
}
