## 6. Globaler ExceptionHandler

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// GlobalExceptionHandler.java
package com.example.secureurlfetch.exception;

import com.example.secureurlfetch.dto.ErrorResponse;
import com.example.secureurlfetch.service.UrlFetchException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ControllerAdvice;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

@ControllerAdvice
public class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    @ExceptionHandler(UrlFetchException.class)
    public ResponseEntity<ErrorResponse> handleUrlFetchException(UrlFetchException ex, WebRequest request) {
        // Generische Fehlermeldung, kein Stacktrace, keine Details
        ErrorResponse body = new ErrorResponse(
                HttpStatus.INTERNAL_SERVER_ERROR.value(),
                "Es ist ein interner Fehler aufgetreten. Bitte versuchen Sie es später erneut.");
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }

    @ExceptionHandler(IllegalArgumentException.class)
    public ResponseEntity<ErrorResponse> handleIllegalArgument(IllegalArgumentException ex, WebRequest request) {
        // Auch hier nur generische Meldung – ggf. eigene Meldung für Validierungsfehler?
        // Sicherheit: Keine Details über die Art des Fehlers
        ErrorResponse body = new ErrorResponse(
                HttpStatus.BAD_REQUEST.value(),
                "Ungültige Anfrage. Überprüfen Sie die Parameter.");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(body);
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<ErrorResponse> handleGeneral(Exception ex, WebRequest request) {
        // Fallback für alle anderen Fehler
        ErrorResponse body = new ErrorResponse(
                HttpStatus.INTERNAL_SERVER_ERROR.value(),
                "Es ist ein interner Fehler aufgetreten.");
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(body);
    }
}
