## 7. Rate-Limiting (Bucket4j)

**Hinweis:** Für Bucket4j muss die Abhängigkeit `com.bucket4j:bucket4j-core:8.x` im `pom.xml` vorhanden sein.

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// RateLimitingInterceptor.java
package com.example.secureurlfetch.interceptor;

import com.example.secureurlfetch.dto.ErrorResponse;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import java.io.IOException;
import java.time.Duration;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Component
public class RateLimitingInterceptor implements HandlerInterceptor {

    private final Map<String, Bucket> buckets = new ConcurrentHashMap<>();
    private final ObjectMapper objectMapper = new ObjectMapper();

    // Rate: 10 Anfragen pro Minute pro IP
    private static final int REQUESTS_PER_MINUTE = 10;

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) throws IOException {
        String clientIp = request.getRemoteAddr();

        Bucket bucket = buckets.computeIfAbsent(clientIp, ip -> createNewBucket());

        if (bucket.tryConsume(1)) {
            return true;
        } else {
            // Rate-Limit überschritten → 429 Too Many Requests
            response.setStatus(HttpStatus.TOO_MANY_REQUESTS.value());
            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
            ErrorResponse errorBody = new ErrorResponse(
                    HttpStatus.TOO_MANY_REQUESTS.value(),
                    "Zu viele Anfragen. Bitte warten Sie einen Moment.");
            objectMapper.writeValue(response.getWriter(), errorBody);
            return false;
        }
    }

    private Bucket createNewBucket() {
        Bandwidth limit = Bandwidth.simple(REQUESTS_PER_MINUTE, Duration.ofMinutes(1));
        return Bucket4j.builder().addLimit(limit).build();
    }
}
