## 8. IP-Blocking-Filter

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// IpBlockingFilter.java
package com.example.secureurlfetch.filter;

import com.example.secureurlfetch.dto.ErrorResponse;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.*;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.core.annotation.Order;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;

import java.io.IOException;
import java.util.Set;

@Component
@Order(1) // Vor Rate-Limiting-Interceptor (oder danach – je nach Präferenz)
public class IpBlockingFilter implements Filter {

    // Beispielhafte Liste blockierter IPs (könnte aus DB/Config kommen)
    private static final Set<String> BLOCKED_IPS = Set.of(
            "192.168.1.100",
            "10.0.0.99"
    );

    private final ObjectMapper objectMapper = new ObjectMapper();

    @Override
    public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse, FilterChain chain)
            throws IOException, ServletException {

        HttpServletRequest request = (HttpServletRequest) servletRequest;
        HttpServletResponse response = (HttpServletResponse) servletResponse;

        String clientIp = request.getRemoteAddr();
        if (BLOCKED_IPS.contains(clientIp)) {
            response.setStatus(HttpStatus.FORBIDDEN.value());
            response.setContentType(MediaType.APPLICATION_JSON_VALUE);
            ErrorResponse errorBody = new ErrorResponse(
                    HttpStatus.FORBIDDEN.value(),
                    "Zugriff von Ihrer IP-Adresse wurde blockiert.");
            objectMapper.writeValue(response.getWriter(), errorBody);
            return;
        }

        chain.doFilter(servletRequest, servletResponse);
    }
}
", "fileName": "Component_8", "vulnerbility": null}, {"type": "TEXT", "text": "

**Erklärung:**  
Ein einfacher Servlet-Filter prüft die Client-IP gegen eine vordefinierte Blockliste. Blockierte IPs erhalten HTTP 403 ohne Detailinformationen. Die Liste kann dynamisch aus einer Datenbank geladen werden.

