## 9. Sicherheitskonfiguration (Spring Security)

"}, {"type": "CODE_BLOCK", "language": "java", "content": "// SecurityConfig.java
package com.example.secureurlfetch.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.core.userdetails.User;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.provisioning.InMemoryUserDetailsManager;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
@EnableMethodSecurity
public class SecurityConfig {

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(authz -> authz
                .requestMatchers("/api/fetch").hasRole("USER")
                .anyRequest().denyAll()
            )
            .httpBasic()
            .and()
            .csrf().disable() // Für REST-API (CSRF-Schutz nicht notwendig bei tokenbasiert, hier basic)
            .sessionManagement().disable();

        return http.build();
    }

    @Bean
    public UserDetailsService userDetailsService() {
        UserDetails user = User.builder()
                .username("user")
                .password(passwordEncoder().encode("password"))
                .roles("USER")
                .build();
        return new InMemoryUserDetailsManager(user);
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder();
    }
}
", "fileName": "Component_9", "vulnerbility": null}, {"type": "TEXT", "text": "

**Erklärung (CWE-284):**  
Der Endpunkt `"/api/fetch"` ist nur für Benutzer mit Rolle `USER` zugänglich. Authentifizierung erfolgt per HTTP Basic Auth, wobei die Passwörter mit BCrypt gespeichert werden. Method-Level-Sicherheit wird durch `@EnableMethodSecurity` und die Annotation `@PreAuthorize` im Controller realisiert.

